SELECT COUNT(DISTINCT "nct") AS "number_of_trials", "total_sample_size", "follow_up_duration_for_primary_endpoint_s_in_months_rx" AS "rx_arm_months", "follow_up_duration_for_primary_endpoint_s_in_months_control" AS "control_arm_months" FROM public."clinical_trials" WHERE "cancer_type" ILIKE '%breast%' GROUP BY "total_sample_size", "follow_up_duration_for_primary_endpoint_s_in_months_rx", "follow_up_duration_for_primary_endpoint_s_in_months_control";